define(['jquery','ko','uiComponent','Magento_Customer/js/customer-data'],function($,ko,Component,customerData){'use strict';return Component.extend({defaults:{template:'Mab_CheckoutCustomization/gift-card/simple'},initialize:function(){this._super();this.initObservable();return this;},initObservable:function(){this.giftCardCode=ko.observable('');this.isApplying=ko.observable(false);this.errorMessage=ko.observable('');this.successMessage=ko.observable('');this.appliedCards=ko.observableArray([]);this.canApply=ko.pureComputed(function(){var code=this.giftCardCode().trim();return code.length>=6&&/^[A-Z0-9-]+$/i.test(code)&&!this.isApplying();},this);return this;},applyGiftCard:function(){var self=this;var code=self.giftCardCode().trim();if(!code||!self.canApply()){return;}
self.errorMessage('');self.successMessage('');self.isApplying(true);$.ajax({url:'/rest/V1/carts/mine/giftCard',type:'POST',contentType:'application/json',data:JSON.stringify({giftCardCode:code}),success:function(response){self.successMessage('Carte cadeau appliquée avec succès!');self.appliedCards.push({code:code,amount:response.discount||'0,00 DZD'});self.giftCardCode('');setTimeout(function(){self.successMessage('');},5000);var sections=['cart'];customerData.invalidate(sections);customerData.reload(sections,true);},error:function(xhr){var error='Échec de l\'application de la carte cadeau. Veuillez vérifier le code et réessayer.';try{var response=JSON.parse(xhr.responseText);if(response.message){error=response.message;}}catch(e){}
self.errorMessage(error);setTimeout(function(){self.errorMessage('');},5000);},complete:function(){self.isApplying(false);}});},removeGiftCard:function(card){var self=this;self.appliedCards.remove(card);$.ajax({url:'/rest/V1/carts/mine/giftCard',type:'DELETE',contentType:'application/json',data:JSON.stringify({giftCardCode:card.code}),success:function(){self.successMessage('Carte cadeau retirée');setTimeout(function(){self.successMessage('');},3000);var sections=['cart'];customerData.invalidate(sections);customerData.reload(sections,true);},error:function(){self.appliedCards.push(card);self.errorMessage('Échec de la suppression de la carte cadeau');setTimeout(function(){self.errorMessage('');},3000);}});}});});